<?php
namespace Tests\Feature\Reporting;
use App\Services\Reporting\{DiagnosticSourceEvidence,DiagnosticBillEvidence,DiagnosticSourceCollection};
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\{DB,Schema};
use Illuminate\Validation\ValidationException;
use Tests\TestCase;
class RetainedPaymentEvidenceTest extends TestCase
{
 protected function setUp():void{parent::setUp();Schema::dropAllTables();config(['app.timezone'=>'UTC','reporting_connector.timezone'=>'UTC']);$this->travelTo(\Carbon\Carbon::parse('2026-11-15 12:00:00','UTC'));
  Schema::create('companies',function(Blueprint $t){$t->id();$t->string('name');$t->string('product_type');});DB::table('companies')->insert([['id'=>1,'name'=>'Synthetic DI','product_type'=>'di'],['id'=>2,'name'=>'Synthetic FBR','product_type'=>'fbrpos'],['id'=>3,'name'=>'Other FBR','product_type'=>'fbrpos'],['id'=>4,'name'=>'Synthetic PRA','product_type'=>'pos']]);
  Schema::create('branches',function(Blueprint $t){$t->id();$t->unsignedBigInteger('company_id');});DB::table('branches')->insert([['id'=>1,'company_id'=>2],['id'=>2,'company_id'=>2],['id'=>3,'company_id'=>3],['id'=>4,'company_id'=>1]]);
  Schema::create('customer_ledgers',function(Blueprint $t){$t->id();$t->unsignedBigInteger('company_id');$t->unsignedBigInteger('invoice_id')->nullable();$t->string('type');$t->string('customer_name');$t->decimal('credit');$t->dateTime('created_at');});
  Schema::create('pos_customers',function(Blueprint $t){$t->id();$t->unsignedBigInteger('company_id');});DB::table('pos_customers')->insert([['id'=>10,'company_id'=>2],['id'=>20,'company_id'=>3]]);
  foreach(['fbr_pos_transactions','pos_transactions','invoices']as$table)Schema::create($table,function(Blueprint $t){$t->id();$t->unsignedBigInteger('company_id');$t->unsignedBigInteger('customer_id')->nullable();$t->unsignedBigInteger('branch_id')->nullable();});
  DB::table('fbr_pos_transactions')->insert([['id'=>1,'company_id'=>2,'customer_id'=>10,'branch_id'=>1],['id'=>2,'company_id'=>2,'customer_id'=>10,'branch_id'=>2],['id'=>3,'company_id'=>3,'customer_id'=>20,'branch_id'=>3]]);DB::table('invoices')->insert(['id'=>1,'company_id'=>1]);DB::table('pos_transactions')->insert(['id'=>1,'company_id'=>4]);
  Schema::create('fbr_customer_ledgers',function(Blueprint $t){$t->id();$t->unsignedBigInteger('company_id');$t->unsignedBigInteger('customer_id');$t->string('entry_type');$t->unsignedBigInteger('transaction_id')->nullable();});
  Schema::create('fbr_khata_settlements',function(Blueprint $t){$t->id();$t->unsignedBigInteger('company_id');$t->unsignedBigInteger('customer_id');$t->unsignedBigInteger('settlement_ledger_id');$t->unsignedBigInteger('credit_ledger_id');$t->decimal('amount');$t->dateTime('created_at');});
  (require database_path('migrations/2026_12_10_040000_create_diagnostic_source_observations.php'))->up();
 }
 private function event(int $id=1):void{DB::table('customer_ledgers')->insert(['id'=>$id,'company_id'=>1,'invoice_id'=>null,'type'=>'payment','customer_name'=>'PRIVATE CUSTOMER','credit'=>123.45,'created_at'=>'2026-11-15 10:00:00']);}
 private function allocation(int $id=1,int $bill=1,string $kind='wasooli'):void{foreach([[$id*2,'udhaar',$bill],[$id*2+1,$kind,null]]as[$ledger,$type,$transaction])DB::table('fbr_customer_ledgers')->insert(['id'=>$ledger,'company_id'=>2,'customer_id'=>10,'entry_type'=>$type,'transaction_id'=>$transaction]);DB::table('fbr_khata_settlements')->insert(['id'=>$id,'company_id'=>2,'customer_id'=>10,'settlement_ledger_id'=>$id*2+1,'credit_ledger_id'=>$id*2,'amount'=>789.12,'created_at'=>'2026-11-15 10:00:00']);}
 private function source(string $source,array $extra=[]):array{return app(DiagnosticSourceEvidence::class)->read($extra+['company_name'=>str_starts_with($source,'di.')?'Synthetic DI':'Synthetic FBR','source'=>$source,'date_from'=>'2026-11-15'],[1,2]);}
 public function test_di_tenant_events_have_no_bill_or_branch_link_and_no_private_values():void{$this->event();$r=$this->source('di.payment_events');self::assertSame([1],array_column($r['rows'],'id'));self::assertSame(['id','event_at'],array_keys($r['rows'][0]));self::assertSame('UNAVAILABLE',$r['payment_evidence']['bill_linkage']);self::assertStringNotContainsString('PRIVATE',json_encode($r));self::assertStringNotContainsString('123.45',json_encode($r));self::assertSame('BRANCH_SCOPE_UNAVAILABLE',$this->source('di.payment_events',['branch_id'=>4])['status']);$bill=app(DiagnosticBillEvidence::class)->read(['company_name'=>'Synthetic DI','bill_id'=>1],[1]);self::assertContains('payments',$bill['unimplemented_links']);}
 public function test_di_unexpected_invoice_link_is_inconsistent_not_inferred_payment():void{$this->event();DB::table('customer_ledgers')->where('id',1)->update(['invoice_id'=>1]);self::assertSame('INCONSISTENT_RETAINED_LINKS',$this->source('di.payment_events')['status']);}
 public function test_fbr_exact_branch_chain_and_bill_only_link_exclude_return_adjustments():void{$this->allocation();$this->allocation(2,2);$this->allocation(3,1,'return_adjust');$r=$this->source('fbrpos.payment_allocations',['branch_id'=>1]);self::assertSame([1],array_column($r['rows'],'id'));self::assertStringNotContainsString('789.12',json_encode($r));$bill=app(DiagnosticBillEvidence::class)->read(['company_name'=>'Synthetic FBR','bill_id'=>1],[2]);self::assertSame([['id'=>1]],$bill['sources']['payment_allocations']['rows']);$pra=app(DiagnosticBillEvidence::class)->read(['company_name'=>'Synthetic PRA','bill_id'=>1],[4]);self::assertArrayNotHasKey('payment_allocations',$pra['sources']);}
 public function test_corrupt_tenant_or_customer_chain_is_explicit_and_has_no_rows():void{$this->allocation();foreach([['company_id'=>3],['customer_id'=>20],['transaction_id'=>3]]as$bad){DB::table('fbr_customer_ledgers')->where('id',2)->update($bad);$r=$this->source('fbrpos.payment_allocations');self::assertSame('INCONSISTENT_RETAINED_LINKS',$r['status']);self::assertSame([],$r['rows']);DB::table('fbr_customer_ledgers')->where('id',2)->update(['company_id'=>2,'customer_id'=>10,'transaction_id'=>1]);}}
 public function test_id_cursor_retains_late_arrival_and_no_complete_claim():void{$this->allocation();$this->allocation(2);$first=$this->source('fbrpos.payment_allocations',['limit'=>1]);self::assertSame(1,$first['pagination']['next_after_id']);$this->allocation(3);$next=$this->source('fbrpos.payment_allocations',['after_id'=>1]);self::assertSame([2,3],array_column($next['rows'],'id'));self::assertFalse($next['coverage']['seven_day_complete']);}
 public function test_source_product_and_authorized_company_are_enforced():void{$this->expectException(ValidationException::class);$this->source('di.payment_events',['company_name'=>'Synthetic FBR']);}
 public function test_foreign_branch_and_oauth_scope_are_denied():void {
  foreach([['company_name'=>'Synthetic FBR','branch_id'=>3],['company_name'=>'Other FBR']]as$extra){
   try{$this->source('fbrpos.payment_allocations',$extra);self::fail('Foreign scope accepted');}catch(ValidationException $e){self::assertNotEmpty($e->errors());}
  }
 }
 public function test_missing_source_schema_is_unavailable_not_empty():void {Schema::drop('fbr_customer_ledgers');self::assertSame('UNAVAILABLE',$this->source('fbrpos.payment_allocations')['status']);}
 public function test_collector_records_explicit_integrity_status_and_count_only():void{$this->allocation();$collector=app(DiagnosticSourceCollection::class);self::assertSame('OBSERVED',$collector->capture(2,'fbrpos.payment_allocations','2026-11-15',(string)\Illuminate\Support\Str::uuid()));DB::table('fbr_customer_ledgers')->where('id',2)->update(['customer_id'=>20]);self::assertSame('INCONSISTENT_RETAINED_LINKS',$collector->capture(2,'fbrpos.payment_allocations','2026-11-15',(string)\Illuminate\Support\Str::uuid()));self::assertSame(2,DB::table('diagnostic_source_observations')->count());}
}
